CREATE TABLE `pq_questions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `section_id` int NOT NULL,
  `variant_target` enum('All','Principal','Distributor','Retail','Contractor','Goods','Supplier') COLLATE utf8mb4_unicode_ci DEFAULT 'All',
  `question_text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `help_text` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `section_id` (`section_id`),
  CONSTRAINT `fk_question_section` FOREIGN KEY (`section_id`) REFERENCES `pq_sections` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
