DROP TABLE IF EXISTS `pq_sla_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pq_sla_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `submission_id` int NOT NULL,
  `leg_number` tinyint NOT NULL DEFAULT '1' COMMENT '1st attempt, 2nd after sendback, etc.',
  `sourcing_submitted_at` datetime NOT NULL COMMENT 'When sourcing fired approve_sourcing',
  `sourcing_reviewer_id` int DEFAULT NULL,
  `sla_deadline` datetime NOT NULL COMMENT 'sourcing_submitted_at + 3 working days',
  `vm_action_at` datetime DEFAULT NULL COMMENT 'When VM acted (NULL = still open)',
  `vm_action_type` enum('forward_head','returned_to_sourcing') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vm_reviewer_id` int DEFAULT NULL,
  `working_hours_elapsed` decimal(6,2) DEFAULT NULL COMMENT 'Actual working hours elapsed (9-12 + 13-18 windows, weekend/holiday excluded)',
  `sla_met` tinyint(1) DEFAULT NULL COMMENT '1 = within 3 days, 0 = breached',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_submission_id` (`submission_id`),
  KEY `idx_open_legs` (`submission_id`,`vm_action_at`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `pq_sla_logs` WRITE;
/*!40000 ALTER TABLE `pq_sla_logs` DISABLE KEYS */;
