DROP TABLE IF EXISTS `pq_submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pq_submissions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `status` enum('draft','under_review_sourcing','under_review_vm','under_review_vm_head','revision_needed','approved','rejected','returned_to_sourcing') COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `total_weighted_score` int DEFAULT '0',
  `max_possible_weighted_score` int DEFAULT '0',
  `risk_percentage` decimal(5,2) DEFAULT '0.00',
  `risk_category` enum('Low Risk','Medium Risk','High Risk') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourcing_reviewer_id` int DEFAULT NULL,
  `sourcing_notes` text COLLATE utf8mb4_unicode_ci,
  `vm_reviewer_id` int DEFAULT NULL,
  `vm_notes` text COLLATE utf8mb4_unicode_ci,
  `submitted_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `pq_sla_deadline` datetime DEFAULT NULL COMMENT 'Active SLA deadline for current leg (for dashboard display)',
  `pq_sla_first_forward_at` datetime DEFAULT NULL COMMENT 'Timestamp of the very first forward_head action (final SLA anchor)',
  `pq_sla_final_hours` decimal(6,2) DEFAULT NULL COMMENT 'Working hours from last sourcing submission to first forward_head',
  `pq_sla_final_met` tinyint(1) DEFAULT NULL COMMENT '1 = within 16h SLA, 0 = breached',
  PRIMARY KEY (`id`),
  KEY `vendor_id` (`vendor_id`),
  CONSTRAINT `fk_submission_vendor` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `pq_submissions` WRITE;
/*!40000 ALTER TABLE `pq_submissions` DISABLE KEYS */;
