  `k2_registered_by` int DEFAULT NULL,
  `admin_notes` text COLLATE utf8mb4_unicode_ci,
  `nib_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contact_person` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pic_finance` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_pic_finance` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_branch` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_account_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_holder_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `goods_services_list` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
