  `sppkp_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_sppkp` tinyint(1) NOT NULL DEFAULT '1',
  `registration_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `director_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `director_phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
