  `deed_of_establishment_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deed_of_amendment_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decree_of_legal_entity_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `decree_of_legal_entity_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
